
/* ---------- 10. Super admin dashboard ---------- */
function viewAdmin() {
  const pf = platformFinance(), customers = db.users.filter((u) => u.role === 'customer');
  const paid = db.bookings.filter((b) => ['paid', 'partially_refunded', 'refunded'].includes(b.paymentStatus));
  const g = monthly(paid, 6, (b) => b.total), cm = monthly(paid, 6, (b) => b.commission);
  const pendC = db.companies.filter((c) => c.status === 'pending'), pendR = db.refunds.filter((r) => r.status === 'pending');
  return dashLayout('admin', tr('نظرة عامة على المنصة', 'Platform overview'), `
  <div class="kpis">${kpi(tr('قيمة الحجوزات (GMV)', 'Booking value (GMV)'), money(pf.gmv), tr(`${fmtN(paid.length)} حجز مدفوع`, `${fmtN(paid.length)} paid bookings`), 'money', true)}${kpi(tr('إيراد المنصة (العمولة)', 'Platform revenue'), money(pf.commission), tr(`عمولة افتراضية ${db.settings.commission}٪`, `Default rate ${db.settings.commission}%`), 'chart')}${kpi(tr('الشركات', 'Companies'), db.companies.filter((c) => c.status === 'approved').length, pendC.length ? `<a class="btn-link" href="#/admin/companies">${tr(`${pendC.length} طلب بانتظار المراجعة`, `${pendC.length} awaiting review`)}</a>` : tr('لا توجد طلبات معلقة', 'No pending applications'), 'building')}${kpi(tr('العملاء', 'Customers'), fmtN(customers.length), tr(`${db.trips.filter((t) => t.status === 'active').length} رحلة منشورة · ${fmtN(db.bookings.length)} حجز`, `${db.trips.filter((t) => t.status === 'active').length} live trips · ${fmtN(db.bookings.length)} bookings`), 'users')}</div>
  <div class="grid" style="grid-template-columns:1.6fr 1fr;margin-top:20px;align-items:start" id="ad-grid">
    <div class="card"><div class="card-h"><h3>${tr('قيمة الحجوزات والعمولة شهريًا', 'Monthly GMV & commission')}</h3></div><div class="card-pad">${barChart({ labels: g.map((x) => x.label), series: [{ name: 'GMV', color: '#16324F', values: g.map((x) => x.v) }, { name: tr('العمولة', 'Commission'), color: '#E9B872', values: cm.map((x) => x.v) }] })}</div></div>
    <div class="card"><div class="card-h"><h3>${tr('يحتاج إجراء', 'Needs action')}</h3></div><div class="card-pad stack">
      ${pendC.map((c) => `<div class="row between"><div class="row">${coLogo(c)}<div><b class="small" style="color:var(--navy)">${esc(L(c.name))}</b><div class="xs muted">${tr('طلب تسجيل', 'Application')} · ${ago(c.createdAt)}</div></div></div><a class="btn btn-soft btn-sm" href="#/admin/companies">${tr('مراجعة', 'Review')}</a></div>`).join('')}
      ${pendR.map((r) => { const b = byId(db.bookings, r.bookingId); return `<div class="row between"><div><b class="small ref">${b.ref}</b><div class="xs muted">${tr('استرداد', 'Refund')} ${money(r.amount)} · ${ago(r.createdAt)}</div></div><a class="btn btn-soft btn-sm" href="#/admin/bookings" data-a="go-refunds">${tr('مراجعة', 'Review')}</a></div>`; }).join('')}
      ${db.trips.filter((t) => t.status === 'pending').map((t) => `<div class="row between"><div><b class="small" style="color:var(--navy)">${esc(L(t.title)).slice(0, 34)}</b><div class="xs muted">${tr('رحلة بانتظار الاعتماد', 'Trip awaiting approval')}</div></div><a class="btn btn-soft btn-sm" href="#/admin/trips">${tr('مراجعة', 'Review')}</a></div>`).join('')}
      ${db.disputes.filter((d) => d.status === 'open').map((d) => `<div class="row between"><div><b class="small" style="color:var(--navy)">${esc(d.subject)}</b><div class="xs muted">${tr('شكوى', 'Complaint')} · ${ago(d.createdAt)}</div></div><a class="btn btn-soft btn-sm" href="#/admin/bookings" data-a="go-disputes">${tr('مراجعة', 'Review')}</a></div>`).join('')}
      ${!pendC.length && !pendR.length ? `<p class="muted small">${tr('كل شيء تمام.', 'All clear.')}</p>` : ''}</div></div></div>
  <div class="grid g2" style="margin-top:20px;align-items:start">
    <div class="card"><div class="card-h"><h3>${tr('آخر النشاطات', 'Recent activity')}</h3></div><div class="card-pad">${db.activity.slice(0, 8).map((a) => `<div class="row between small" style="padding:7px 0;border-bottom:1px solid var(--line-2)"><span>${esc(L(a.text))}</span><span class="xs faint" style="white-space:nowrap">${ago(a.at)}</span></div>`).join('')}</div></div>
    <div class="card"><div class="card-h"><h3>${tr('أداء الشركات', 'Company performance')}</h3><a class="btn-link small" href="#/admin/finance">${tr('المالية', 'Finance')}</a></div><div class="tbl-wrap"><table class="tbl"><thead><tr><th>${tr('الشركة', 'Company')}</th><th>${tr('الحجوزات', 'Bookings')}</th><th>${tr('القيمة', 'Value')}</th><th>${tr('التقييم', 'Rating')}</th></tr></thead><tbody>${db.companies.filter((c) => c.status === 'approved').map((c) => { const f = companyFinance(c.id), r = companyRating(c.id); return `<tr><td><div class="row">${coLogo(c)}${esc(L(c.name))}</div></td><td class="num">${f.count}</td><td class="num">${money(f.gross)}</td><td>${starsHTML(r.avg)}</td></tr>`; }).join('')}</tbody></table></div></div></div>
  <style>@media(max-width:1100px){#ad-grid{grid-template-columns:1fr!important}}</style>`);
}
ACTIONS['go-refunds'] = () => { UI.adBkTab = 'refunds'; go('#/admin/bookings'); };
ACTIONS['go-disputes'] = () => { UI.adBkTab = 'disputes'; go('#/admin/bookings'); };

/* companies */
function viewAdCompanies() {
  const rows = db.companies.map((c) => ({ ...c, _n: L(c.name), fin: companyFinance(c.id), trips: db.trips.filter((t) => t.companyId === c.id).length }));
  UI.tableState.adco = UI.tableState.adco || { q: '', sort: 'createdAt', dir: 'desc', page: 0, f: db.companies.some((c) => c.status === 'pending') ? { status: 'pending' } : {} };
  return dashLayout('admin', tr('الشركات', 'Companies'), dataTable({ id: 'adco', rows, searchText: (r) => r._n + ' ' + r.email + ' ' + r.license, emptyIcon: 'building',
    filters: [{ key: 'status', label: tr('كل الحالات', 'All statuses'), options: Object.entries(CSTAT).map(([k, v]) => [k, L(v.l)]), test: (r, v) => r.status === v }],
    cols: [{ key: '_n', label: tr('الشركة', 'Company'), render: (r) => `<div class="row">${coLogo(r, 'md')}<div><b style="color:var(--navy)">${esc(r._n)}</b><div class="xs muted">${esc(L(r.city))} · ${esc(r.email)}</div></div></div>` }, { key: 'status', label: tr('الحالة', 'Status'), render: (r) => badge(CSTAT, r.status) }, { key: 'trips', label: tr('الرحلات', 'Trips'), render: (r) => `<span class="num">${r.trips}</span>` }, { key: 'gross', label: tr('قيمة الحجوزات', 'Booking value'), sortVal: (r) => r.fin.gross, render: (r) => `<span class="num">${money(r.fin.gross)}</span>` }, { key: 'commission', label: tr('العمولة', 'Rate'), sortVal: (r) => effectiveRate(r), render: (r) => `${effectiveRate(r)}٪${r.commission != null ? ` <span class="badge b-teal" style="padding:0 6px">${tr('خاصة', 'custom')}</span>` : ''}` }, { key: 'createdAt', label: tr('التسجيل', 'Joined'), render: (r) => `<span class="small">${fmtD(r.createdAt)}</span>` },
      { key: '', label: '', sort: false, render: (r) => `<div class="row" style="gap:6px;justify-content:flex-end">${r.status === 'pending' ? `<button class="btn btn-ok-soft btn-sm" data-a="co-approve" data-id="${r.id}">${ic('check')}${tr('اعتماد', 'Approve')}</button><button class="btn btn-danger-soft btn-sm" data-a="co-reject" data-id="${r.id}">${tr('رفض', 'Reject')}</button>` : ''}<button class="btn btn-ghost btn-sm" data-a="co-view" data-id="${r.id}">${tr('عرض', 'View')}</button>${r.status === 'approved' ? `<button class="icon-btn" data-a="co-suspend" data-id="${r.id}" title="${tr('إيقاف', 'Suspend')}" aria-label="${tr('إيقاف', 'Suspend')}">${ic('ban')}</button>` : r.status === 'suspended' ? `<button class="btn btn-soft btn-sm" data-a="co-activate" data-id="${r.id}">${tr('تفعيل', 'Activate')}</button>` : ''}</div>` }] }));
}
ACTIONS['co-approve'] = async (el) => {
  const c = compById(el.dataset.id);
  if (!(await confirmDialog({ title: tr('اعتماد الشركة؟', 'Approve this company?'), text: tr(`${L(c.name)} هتقدر تنشر رحلات وتستقبل حجوزات. اتأكد إنك راجعت المستندات: ${(c.docs || []).map((d) => d.name).join('، ')}.`, `${L(c.name)} will be able to publish trips and take bookings. Make sure you reviewed: ${(c.docs || []).map((d) => d.name).join(', ')}.`), ok: tr('اعتماد', 'Approve') }))) return;
  tx((d) => { const x = byId(d.companies, c.id); x.status = 'approved'; x.approvedAt = new Date().toISOString(); notify(d, 'company:' + c.id, { ar: 'تم اعتماد شركتك', en: 'Your company is approved' }, { ar: 'تقدر دلوقتي تضيف رحلاتك ومواعيدها.', en: 'You can now add your trips and departures.' }, '#/co/trips'); logAct(d, `تم اعتماد ${x.name.ar}`, `${x.name.en} approved`); });
  closeModal(); toast(tr(`تم اعتماد ${L(c.name)} وإرسال إشعار لها.`, `${L(c.name)} approved and notified.`)); render();
};
ACTIONS['co-reject'] = async (el) => {
  const c = compById(el.dataset.id);
  const reason = await confirmDialog({ title: tr('رفض الطلب', 'Reject application'), text: tr(`هيتبعت سبب الرفض لـ ${L(c.name)}.`, `The reason will be sent to ${L(c.name)}.`), ok: tr('رفض الطلب', 'Reject'), danger: true, input: tr('سبب الرفض', 'Reason') });
  if (reason === false) return;
  tx((d) => { const x = byId(d.companies, c.id); x.status = 'rejected'; x.rejectReason = reason; notify(d, 'company:' + c.id, { ar: 'تم رفض الطلب', en: 'Application declined' }, { ar: reason || 'تواصل معنا للتفاصيل.', en: reason || 'Contact us for details.' }, '#/co'); logAct(d, `تم رفض ${x.name.ar}`, `${x.name.en} rejected`); });
  closeModal(); toast(tr('تم رفض الطلب.', 'Application rejected.')); render();
};
ACTIONS['co-suspend'] = async (el) => { const c = compById(el.dataset.id); if (!(await confirmDialog({ title: tr('إيقاف الشركة؟', 'Suspend company?'), text: tr('كل رحلات الشركة هتختفي من الموقع، والحجوزات الحالية هتفضل كما هي.', 'All its trips disappear from the site; existing bookings stay as they are.'), ok: tr('إيقاف', 'Suspend'), danger: true }))) return; tx((d) => { byId(d.companies, c.id).status = 'suspended'; notify(d, 'company:' + c.id, { ar: 'تم إيقاف الحساب', en: 'Account suspended' }, { ar: 'تواصل مع إدارة رحلاتي.', en: 'Contact Rehlati support.' }, '#/co'); }); closeModal(); toast(tr('تم إيقاف الشركة.', 'Company suspended.')); render(); };
ACTIONS['co-activate'] = (el) => { tx((d) => { byId(d.companies, el.dataset.id).status = 'approved'; notify(d, 'company:' + el.dataset.id, { ar: 'تم تفعيل الحساب', en: 'Account reactivated' }, { ar: 'رحلاتك ظاهرة للعملاء مرة أخرى.', en: 'Your trips are visible again.' }, '#/co'); }); toast(tr('تم تفعيل الشركة.', 'Company activated.')); render(); };
ACTIONS['co-view'] = (el) => {
  const c = compById(el.dataset.id), f = companyFinance(c.id), r = companyRating(c.id), trips = db.trips.filter((t) => t.companyId === c.id);
  modal({ wide: true, title: esc(L(c.name)), body: `<div class="row wrapx" style="gap:8px;margin-bottom:14px">${badge(CSTAT, c.status)}<span class="small muted">${tr('سجلت', 'Joined')} ${fmtD(c.createdAt)}</span></div>
    <div class="kpis" style="margin-bottom:16px">${kpi(tr('قيمة الحجوزات', 'Value'), money(f.gross), '', 'money')}${kpi(tr('العمولة', 'Commission'), money(f.commission), '', 'chart')}${kpi(tr('الرحلات', 'Trips'), trips.length, '', 'map')}${kpi(tr('التقييم', 'Rating'), r.count ? r1(r.avg) : '—', tr(`${r.count} تقييم`, `${r.count} reviews`), 'star')}</div>
    <form data-f="ad-co-edit" data-id="${c.id}" id="adco-form" novalidate class="form-grid">${inp('name_ar', tr('الاسم (عربي)', 'Name (Arabic)'), c.name.ar)}${inp('name_en', tr('الاسم (إنجليزي)', 'Name (English)'), c.name.en, { attrs: 'dir="ltr"' })}${inp('phone', tr('الموبايل', 'Mobile'), c.phone, { attrs: 'dir="ltr"' })}${inp('email', tr('البريد', 'Email'), c.email, { attrs: 'dir="ltr"' })}${inp('license', tr('الترخيص', 'Licence'), c.license)}${inp('commission', tr('عمولة خاصة ٪ (اتركها فارغة للافتراضي)', 'Custom commission % (blank = default)'), c.commission == null ? '' : c.commission, { type: 'number', attrs: 'min="0" max="50" step="0.5"', hint: tr(`الافتراضي ${db.settings.commission}٪`, `Default ${db.settings.commission}%`) })}</form>
    <h4 style="margin:18px 0 8px">${tr('المستندات', 'Documents')}</h4>${(c.docs || []).map((d) => `<div class="row small" style="padding:4px 0">${ic('doc')}${esc(d.name)}</div>`).join('')}`,
    foot: `${c.status === 'pending' ? `<button class="btn btn-danger-soft" data-a="co-reject" data-id="${c.id}">${tr('رفض', 'Reject')}</button><button class="btn btn-ok-soft" data-a="co-approve" data-id="${c.id}">${tr('اعتماد', 'Approve')}</button>` : ''}<button class="btn btn-primary" data-a="adco-save">${tr('حفظ', 'Save')}</button>` });
};
ACTIONS['adco-save'] = () => $('#adco-form').requestSubmit();
FORMS['ad-co-edit'] = (f) => { const d = validate(f, { name_ar: ['req'], phone: ['req', 'phone'], email: ['req', 'email'], commission: ['pct'] }); if (!d) return; tx((x) => { const c = byId(x.companies, f.dataset.id); Object.assign(c, { name: { ar: d.name_ar, en: d.name_en || d.name_ar }, phone: d.phone, email: d.email, license: d.license, commission: d.commission === '' ? null : +d.commission }); }); closeModal(); toast(tr('تم حفظ بيانات الشركة.', 'Company saved.')); render(); };

/* trips */
function viewAdTrips() {
  const rows = db.trips.map((t) => ({ ...t, _n: L(t.title), _c: L(compById(t.companyId).name), s: tripStats(t), featured: db.settings.featuredTrips.includes(t.id) }));
  UI.tableState.adtr = UI.tableState.adtr || { q: '', sort: 'createdAt', dir: 'desc', page: 0, f: db.trips.some((t) => t.status === 'pending') ? { status: 'pending' } : {} };
  return dashLayout('admin', tr('الرحلات', 'Trips'), dataTable({ id: 'adtr', rows, searchText: (r) => r._n + ' ' + r._c, emptyIcon: 'map',
    filters: [{ key: 'status', label: tr('كل الحالات', 'All statuses'), options: Object.entries(TSTAT).map(([k, v]) => [k, L(v.l)]), test: (r, v) => r.status === v }, { key: 'co', label: tr('كل الشركات', 'All companies'), options: db.companies.map((c) => [c.id, L(c.name)]), test: (r, v) => r.companyId === v }, { key: 'dest', label: tr('كل الوجهات', 'All destinations'), options: db.destinations.map((d) => [d.id, L(d.name)]), test: (r, v) => r.destId === v }],
    cols: [{ key: '_n', label: tr('الرحلة', 'Trip'), render: (r) => `<div class="row"><img src="${imgSrc(r.images[0])}" alt="" style="width:56px;height:40px;object-fit:cover;border-radius:8px;flex:none"><div style="min-width:0"><b style="color:var(--navy)">${esc(r._n).slice(0, 46)}</b><div class="xs muted">${esc(L(destById(r.destId).name))} · ${esc(L(catById(r.catId).name))}</div></div></div>` }, { key: '_c', label: tr('الشركة', 'Company') }, { key: 'status', label: tr('الحالة', 'Status'), render: (r) => badge(TSTAT, r.status) + (r.featured ? ` <span class="badge b-teal">${tr('مميزة', 'Featured')}</span>` : '') }, { key: 'price', label: tr('من', 'From'), sortVal: (r) => r.s.minPrice, render: (r) => `<span class="num">${money(r.s.minPrice)}</span>` }, { key: 'rating', label: tr('التقييم', 'Rating'), sortVal: (r) => r.s.rating, render: (r) => starsHTML(r.s.rating, r.s.reviews) },
      { key: '', label: '', sort: false, render: (r) => `<div class="row" style="gap:6px;justify-content:flex-end">${r.status === 'pending' ? `<button class="btn btn-ok-soft btn-sm" data-a="tr-approve" data-id="${r.id}">${tr('اعتماد', 'Approve')}</button><button class="btn btn-danger-soft btn-sm" data-a="tr-reject" data-id="${r.id}">${tr('رفض', 'Reject')}</button>` : ''}<a class="icon-btn" href="#/trip/${r.id}" title="${tr('معاينة', 'Preview')}" aria-label="${tr('معاينة', 'Preview')}">${ic('eye')}</a><button class="icon-btn" data-a="tr-edit" data-id="${r.id}" title="${tr('تعديل', 'Edit')}" aria-label="${tr('تعديل', 'Edit')}">${ic('edit')}</button>${r.status === 'active' ? `<button class="icon-btn" data-a="tr-hide" data-id="${r.id}" title="${tr('إخفاء', 'Hide')}" aria-label="${tr('إخفاء', 'Hide')}">${ic('eyeoff')}</button>` : r.status === 'hidden' ? `<button class="btn btn-soft btn-sm" data-a="tr-unhide" data-id="${r.id}">${tr('إظهار', 'Unhide')}</button>` : ''}</div>` }] }));
}
const trNotify = (d, t, ar, en) => notify(d, 'company:' + t.companyId, { ar, en }, { ar: t.title.ar, en: t.title.en || t.title.ar }, '#/co/trips');
ACTIONS['tr-approve'] = (el) => { tx((d) => { const t = byId(d.trips, el.dataset.id); t.status = 'active'; trNotify(d, t, 'تم اعتماد رحلتك ونشرها', 'Your trip is approved and live'); logAct(d, `تم اعتماد رحلة ${t.title.ar}`, `Trip approved: ${t.title.en || t.title.ar}`); }); toast(tr('تم اعتماد الرحلة ونشرها.', 'Trip approved and published.')); render(); };
ACTIONS['tr-reject'] = async (el) => { const reason = await confirmDialog({ title: tr('رفض الرحلة', 'Reject trip'), text: tr('الشركة هتستلم السبب وتقدر تعدل الرحلة وتعيد إرسالها.', 'The company gets the reason and can edit and resubmit.'), ok: tr('رفض', 'Reject'), danger: true, input: tr('سبب الرفض', 'Reason') }); if (reason === false) return; tx((d) => { const t = byId(d.trips, el.dataset.id); t.status = 'rejected'; t.rejectReason = reason; notify(d, 'company:' + t.companyId, { ar: 'تم رفض الرحلة', en: 'Trip rejected' }, { ar: `${t.title.ar}: ${reason}`, en: `${t.title.en || t.title.ar}: ${reason}` }, '#/co/trips'); }); toast(tr('تم رفض الرحلة.', 'Trip rejected.')); render(); };
ACTIONS['tr-hide'] = async (el) => { if (!(await confirmDialog({ title: tr('إخفاء الرحلة؟', 'Hide trip?'), text: tr('الرحلة هتختفي من الموقع والحجوزات الحالية هتفضل.', 'The trip disappears from the site; existing bookings remain.'), ok: tr('إخفاء', 'Hide'), danger: true }))) return; tx((d) => { const t = byId(d.trips, el.dataset.id); t.status = 'hidden'; trNotify(d, t, 'تم إخفاء رحلتك من الإدارة', 'Your trip was hidden by the admin'); }); toast(tr('تم إخفاء الرحلة.', 'Trip hidden.')); render(); };
ACTIONS['tr-unhide'] = (el) => { tx((d) => { byId(d.trips, el.dataset.id).status = 'active'; }); toast(tr('الرحلة ظاهرة مرة أخرى.', 'Trip visible again.')); render(); };
ACTIONS['tr-edit'] = (el) => { const t = tripById(el.dataset.id); modal({ title: tr('تعديل الرحلة', 'Edit trip'), body: `<form data-f="ad-tr" id="adtr-form" data-id="${t.id}" class="stack" novalidate>${inp('title_ar', tr('العنوان (عربي)', 'Title (Arabic)'), t.title.ar)}${inp('title_en', tr('العنوان (إنجليزي)', 'Title (English)'), t.title.en, { attrs: 'dir="ltr"' })}${sel('destId', tr('الوجهة', 'Destination'), db.destinations.map((d) => [d.id, L(d.name)]), t.destId)}${sel('catId', tr('التصنيف', 'Category'), db.categories.map((c) => [c.id, L(c.name)]), t.catId)}${sel('status', tr('الحالة', 'Status'), Object.entries(TSTAT).map(([k, v]) => [k, L(v.l)]), t.status)}<label class="check"><input type="checkbox" name="featured" value="1" ${db.settings.featuredTrips.includes(t.id) ? 'checked' : ''}>${tr('عرضها ضمن الرحلات المميزة في الرئيسية', 'Feature on the homepage')}</label></form>`, foot: `<button class="btn btn-ghost" data-a="close-modal">${tr('إلغاء', 'Cancel')}</button><button class="btn btn-primary" data-a="adtr-save">${tr('حفظ', 'Save')}</button>` }); };
ACTIONS['adtr-save'] = () => $('#adtr-form').requestSubmit();
FORMS['ad-tr'] = (f) => { const d = validate(f, { title_ar: ['req'] }); if (!d) return; tx((x) => { const t = byId(x.trips, f.dataset.id); Object.assign(t, { title: { ar: d.title_ar, en: d.title_en }, destId: d.destId, catId: d.catId, status: d.status }); const fs = x.settings.featuredTrips.filter((id) => id !== t.id); if (d.featured) fs.push(t.id); x.settings.featuredTrips = fs; }); closeModal(); toast(tr('تم حفظ الرحلة.', 'Trip saved.')); render(); };

/* customers */
function viewAdCustomers() {
  const rows = db.users.filter((u) => u.role === 'customer').map((u) => { const bs = db.bookings.filter((b) => b.customerId === u.id); return { ...u, n: bs.length, spent: sum(bs.filter((b) => b.paymentStatus !== 'pending' && b.paymentStatus !== 'failed'), retained) }; });
  return dashLayout('admin', tr('العملاء', 'Customers'), dataTable({ id: 'adcu', rows, defaultSort: 'createdAt', export: true, exportName: 'customers', searchText: (r) => r.name + ' ' + r.email + ' ' + r.phone, emptyIcon: 'users',
    filters: [{ key: 'status', label: tr('كل الحالات', 'All statuses'), options: [['active', tr('نشط', 'Active')], ['suspended', tr('موقوف', 'Suspended')]], test: (r, v) => r.status === v }],
    cols: [{ key: 'name', label: tr('العميل', 'Customer'), render: (r) => `<div class="row"><span class="avatar">${esc(initials(r.name))}</span><div><b style="color:var(--navy)">${esc(r.name)}</b><div class="xs muted">${esc(r.email)}</div></div></div>`, csv: (r) => r.name }, { key: 'phone', label: tr('الموبايل', 'Mobile'), render: (r) => `<span dir="ltr">${esc(r.phone)}</span>` }, { key: 'n', label: tr('الحجوزات', 'Bookings'), render: (r) => `<span class="num">${r.n}</span>` }, { key: 'spent', label: tr('إجمالي المدفوع', 'Total paid'), render: (r) => `<span class="num">${money(r.spent)}</span>` }, { key: 'createdAt', label: tr('التسجيل', 'Joined'), render: (r) => fmtD(r.createdAt), csv: (r) => r.createdAt.slice(0, 10) }, { key: 'status', label: tr('الحالة', 'Status'), render: (r) => `<span class="badge ${r.status === 'active' ? 'b-ok' : 'b-mute'}">${r.status === 'active' ? tr('نشط', 'Active') : tr('موقوف', 'Suspended')}</span>` },
      { key: '', label: '', sort: false, render: (r) => `<div class="row" style="gap:6px;justify-content:flex-end"><button class="btn btn-ghost btn-sm" data-a="cu-hist" data-id="${r.id}">${tr('سجل الحجوزات', 'History')}</button><button class="btn btn-sm ${r.status === 'active' ? 'btn-danger-soft' : 'btn-soft'}" data-a="cu-toggle" data-id="${r.id}">${r.status === 'active' ? tr('إيقاف', 'Suspend') : tr('تفعيل', 'Activate')}</button></div>` }] }));
}
ACTIONS['cu-toggle'] = async (el) => { const u = userById(el.dataset.id); if (u.status === 'active' && !(await confirmDialog({ title: tr('إيقاف حساب العميل؟', 'Suspend customer?'), text: tr(`${u.name} مش هيقدر يسجل دخول أو يحجز.`, `${u.name} won’t be able to log in or book.`), ok: tr('إيقاف', 'Suspend'), danger: true }))) return; tx((d) => { const x = byId(d.users, u.id); x.status = x.status === 'active' ? 'suspended' : 'active'; }); toast(tr('تم تحديث حالة الحساب.', 'Account status updated.')); render(); };
ACTIONS['cu-hist'] = (el) => { const u = userById(el.dataset.id), bs = db.bookings.filter((b) => b.customerId === u.id).sort((a, b) => b.createdAt.localeCompare(a.createdAt)); modal({ wide: true, title: tr('سجل حجوزات ', 'Bookings of ') + esc(u.name), body: bs.length ? `<div class="tbl-wrap"><table class="tbl"><thead><tr><th>${tr('الحجز', 'Ref')}</th><th>${tr('الرحلة', 'Trip')}</th><th>${tr('الموعد', 'Date')}</th><th>${tr('الإجمالي', 'Total')}</th><th>${tr('الحالة', 'Status')}</th></tr></thead><tbody>${bs.map((b) => `<tr><td class="ref">${b.ref}</td><td class="small">${esc(L(tripById(b.tripId).title)).slice(0, 40)}</td><td>${fmtD(depById(b.departureId).start)}</td><td class="num">${money(b.total)}</td><td>${badge(BSTAT, b.status)}</td></tr>`).join('')}</tbody></table></div>` : `<p class="muted">${tr('لا توجد حجوزات.', 'No bookings.')}</p>` }); };

/* bookings, refunds, disputes */
function viewAdBookings() {
  const tab = UI.adBkTab || 'all';
  const tabs = [['all', tr('كل الحجوزات', 'All bookings'), db.bookings.length], ['refunds', tr('طلبات الاسترداد', 'Refund requests'), db.refunds.filter((r) => r.status === 'pending').length], ['disputes', tr('الشكاوى', 'Disputes'), db.disputes.filter((d) => d.status === 'open').length]];
  let body = '';
  if (tab === 'all') {
    const rows = db.bookings.map((b) => ({ ...b, cust: userById(b.customerId).name, co: L(compById(b.companyId).name), trip: L(tripById(b.tripId).title), dep: depById(b.departureId).start }));
    body = dataTable({ id: 'adbk', rows, defaultSort: 'createdAt', export: true, exportName: 'platform-bookings', searchPh: tr('ابحث برقم الحجز أو اسم العميل', 'Search by ref or customer'), searchText: (r) => r.ref + ' ' + r.cust + ' ' + r.trip,
      filters: [{ key: 'status', label: tr('حالة الحجز', 'Booking status'), options: Object.entries(BSTAT).map(([k, v]) => [k, L(v.l)]), test: (r, v) => r.status === v }, { key: 'pay', label: tr('حالة الدفع', 'Payment'), options: Object.entries(PSTAT).filter(([k]) => k !== 'refund').map(([k, v]) => [k, L(v.l)]), test: (r, v) => r.paymentStatus === v }, { key: 'co', label: tr('كل الشركات', 'All companies'), options: db.companies.map((c) => [c.id, L(c.name)]), test: (r, v) => r.companyId === v }],
      csvCols: [{ label: 'Ref', csv: (r) => r.ref }, { label: tr('العميل', 'Customer'), csv: (r) => r.cust }, { label: tr('الشركة', 'Company'), csv: (r) => r.co }, { label: tr('الرحلة', 'Trip'), csv: (r) => r.trip }, { label: tr('الموعد', 'Departure'), csv: (r) => r.dep }, { label: tr('الإجمالي', 'Total'), csv: (r) => r.total }, { label: tr('العمولة', 'Commission'), csv: (r) => r.commission }, { label: tr('الدفع', 'Payment'), csv: (r) => r.paymentStatus }, { label: tr('الحالة', 'Status'), csv: (r) => r.status }],
      cols: [{ key: 'ref', label: tr('الحجز', 'Ref'), render: (r) => `<button class="btn-link ref" data-a="ad-bk" data-id="${r.id}">${r.ref}</button>` }, { key: 'cust', label: tr('العميل', 'Customer') }, { key: 'co', label: tr('الشركة', 'Company'), render: (r) => `<span class="small">${esc(r.co)}</span>` }, { key: 'dep', label: tr('الموعد', 'Departure'), render: (r) => fmtD(r.dep) }, { key: 'total', label: tr('الإجمالي', 'Total'), render: (r) => `<span class="num">${money(r.total)}</span>` }, { key: 'commission', label: tr('العمولة', 'Commission'), render: (r) => `<span class="num">${money(r.commission)}</span>` }, { key: 'paymentStatus', label: tr('الدفع', 'Payment'), render: (r) => badge(PSTAT, r.paymentStatus) }, { key: 'status', label: tr('الحالة', 'Status'), render: (r) => badge(BSTAT, r.status) }] });
  } else if (tab === 'refunds') {
    const rows = db.refunds.map((r) => { const b = byId(db.bookings, r.bookingId); return { ...r, b, ref: b.ref, cust: userById(b.customerId).name }; });
    UI.tableState.adrf = UI.tableState.adrf || { q: '', sort: 'createdAt', dir: 'desc', page: 0, f: { st: 'pending' } };
    body = dataTable({ id: 'adrf', rows, searchText: (r) => r.ref + ' ' + r.cust, emptyIcon: 'refund', emptyTitle: tr('لا توجد طلبات', 'No requests'), emptyText: tr('طلبات الاسترداد الجديدة هتظهر هنا.', 'New refund requests appear here.'),
      filters: [{ key: 'st', label: tr('كل الطلبات', 'All requests'), options: [['pending', tr('قيد المراجعة', 'Pending')], ['approved', tr('تمت الموافقة', 'Approved')], ['rejected', tr('مرفوض', 'Rejected')]], test: (r, v) => r.status === v }],
      cols: [{ key: 'ref', label: tr('الحجز', 'Booking'), render: (r) => `<button class="btn-link ref" data-a="ad-bk" data-id="${r.b.id}">${r.ref}</button>` }, { key: 'cust', label: tr('العميل', 'Customer') }, { key: 'reason', label: tr('السبب', 'Reason'), render: (r) => `<span class="small">${esc(r.reason === 'departure_cancelled_by_company' ? tr('ألغت الشركة الموعد', 'Operator cancelled the date') : r.reason)}</span>` }, { key: 'amount', label: tr('المبلغ', 'Amount'), render: (r) => `<b class="num">${money(r.amount)}</b> <span class="xs faint">${tr('من', 'of')} ${money(r.b.total)}</span>` }, { key: 'createdAt', label: tr('التاريخ', 'Date'), render: (r) => fmtD(r.createdAt) }, { key: 'status', label: tr('الحالة', 'Status'), render: (r) => `<span class="badge ${r.status === 'pending' ? 'b-warn' : r.status === 'approved' ? 'b-ok' : 'b-bad'}">${r.status === 'pending' ? tr('قيد المراجعة', 'Pending') : r.status === 'approved' ? tr('تمت الموافقة', 'Approved') : tr('مرفوض', 'Rejected')}</span>` },
        { key: '', label: '', sort: false, render: (r) => r.status === 'pending' ? `<div class="row" style="gap:6px;justify-content:flex-end"><button class="btn btn-ok-soft btn-sm" data-a="rf-ok" data-id="${r.id}">${tr('موافقة ورد المبلغ', 'Approve & refund')}</button><button class="btn btn-danger-soft btn-sm" data-a="rf-dec" data-id="${r.id}">${tr('رفض', 'Decline')}</button></div>` : '' }] });
  } else {
    body = `<div class="card">${db.disputes.length ? db.disputes.map((d) => { const b = byId(db.bookings, d.bookingId); return `<div class="notif"><span class="n-ic" style="background:var(--warn-50);color:var(--warn)">${ic('flag')}</span><div class="grow"><b style="color:var(--navy)">${esc(d.subject)}</b><p class="small muted">${tr('حجز', 'Booking')} <button class="btn-link ref" data-a="ad-bk" data-id="${b.id}">${b.ref}</button> · ${esc(userById(b.customerId).name)} · ${esc(L(compById(b.companyId).name))} · ${ago(d.createdAt)}</p>${d.resolution ? `<p class="small" style="margin-top:4px">${tr('الحل:', 'Resolution:')} ${esc(d.resolution)}</p>` : ''}</div>${d.status === 'open' ? `<button class="btn btn-soft btn-sm" data-a="dp-resolve" data-id="${d.id}">${tr('إغلاق الشكوى', 'Resolve')}</button>` : `<span class="badge b-ok">${tr('مغلقة', 'Resolved')}</span>`}</div>`; }).join('') : empty('flag', tr('لا توجد شكاوى', 'No disputes'), '')}</div>`;
  }
  return dashLayout('admin', tr('الحجوزات والاسترداد', 'Bookings & refunds'), `<div class="tabs" role="tablist">${tabs.map(([k, l, n]) => `<button role="tab" aria-selected="${k === tab}" class="${k === tab ? 'on' : ''}" data-a="adbk-tab" data-k="${k}">${l} ${n ? `<span class="faint">(${n})</span>` : ''}</button>`).join('')}</div>${body}`);
}
ACTIONS['adbk-tab'] = (el) => { UI.adBkTab = el.dataset.k; render(); };
ACTIONS['ad-bk'] = (el) => bookingModal(byId(db.bookings, el.dataset.id), 'admin');
ACTIONS['rf-ok'] = async (el) => { const r = byId(db.refunds, el.dataset.id), b = byId(db.bookings, r.bookingId); if (!(await confirmDialog({ title: tr('الموافقة على الاسترداد', 'Approve refund'), text: tr(`هيترد ${money(r.amount)} للعميل على الحجز ${b.ref} بنفس طريقة الدفع. لا يمكن التراجع.`, `${money(r.amount)} will be refunded on ${b.ref} to the original payment method. This can’t be undone.`), ok: tr('رد المبلغ', 'Refund') }))) return; processRefund(r.id, true); closeModal(); toast(tr('تم رد المبلغ وإبلاغ العميل.', 'Refunded and customer notified.')); render(); };
ACTIONS['rf-dec'] = async (el) => { const note = await confirmDialog({ title: tr('رفض الاسترداد', 'Decline refund'), text: tr('الحجز هيرجع مؤكد، والعميل هيستلم السبب.', 'The booking returns to confirmed and the customer gets the reason.'), ok: tr('رفض', 'Decline'), danger: true, input: tr('السبب', 'Reason') }); if (note === false) return; processRefund(el.dataset.id, false, note); closeModal(); toast(tr('تم رفض الطلب.', 'Request declined.')); render(); };
ACTIONS['dp-resolve'] = async (el) => { const res = await confirmDialog({ title: tr('إغلاق الشكوى', 'Resolve dispute'), text: tr('اكتب ملخص الحل اللي اتفقت عليه مع العميل والشركة.', 'Summarise the resolution agreed with the customer and company.'), ok: tr('إغلاق', 'Resolve'), input: tr('الحل', 'Resolution') }); if (res === false) return; tx((d) => { const x = byId(d.disputes, el.dataset.id); x.status = 'resolved'; x.resolution = res; const b = byId(d.bookings, x.bookingId); notify(d, b.customerId, { ar: 'تم حل شكواك', en: 'Your complaint was resolved' }, { ar: res || x.subject, en: res || x.subject }, '#/me/booking/' + b.ref); }); toast(tr('تم إغلاق الشكوى.', 'Dispute resolved.')); render(); };

/* finance */
function viewAdFinance() {
  const pf = platformFinance();
  const rows = db.companies.filter((c) => c.status !== 'pending' && c.status !== 'rejected').map((c) => ({ ...c, _n: L(c.name), f: companyFinance(c.id) }));
  const payable = sum(rows, (r) => r.f.payable), escrow = sum(rows, (r) => r.f.escrow);
  const txs = db.payments.map((p) => ({ ...p, b: byId(db.bookings, p.bookingId) })).filter((p) => p.b);
  return dashLayout('admin', tr('المالية والعمولات', 'Finance & commission'), `
  <div class="kpis">${kpi(tr('إجمالي قيمة الحجوزات', 'Total GMV'), money(pf.gmv), tr(`مسترد ${money(pf.refunds)}`, `${money(pf.refunds)} refunded`), 'money', true)}${kpi(tr('إيراد المنصة', 'Platform revenue'), money(pf.commission), '', 'chart')}${kpi(tr('مستحقات للشركات', 'Payable to companies'), money(payable), tr(`${money(escrow)} محجوز لرحلات لم تتم`, `${money(escrow)} held for upcoming trips`), 'wallet')}${kpi(tr('تسويات منفذة', 'Settlements paid'), money(pf.settled), tr(`${db.settlements.length} تسوية`, `${db.settlements.length} settlements`), 'check')}</div>
  <div class="grid" style="grid-template-columns:1fr 2fr;gap:20px;margin-top:20px;align-items:start" id="fin-grid">
    <form class="card card-pad stack" data-f="ad-comm" novalidate><h3>${tr('العمولة الافتراضية', 'Default commission')}</h3><p class="small muted">${tr('بتنطبق على كل الشركات اللي مالهاش نسبة خاصة. التغيير بيأثر على الحجوزات الجديدة فقط.', 'Applies to every company without a custom rate. Changes affect new bookings only.')}</p>${inp('commission', tr('النسبة ٪', 'Rate %'), db.settings.commission, { type: 'number', attrs: 'min="0" max="50" step="0.5"' })}<button class="btn btn-primary" type="submit">${tr('حفظ النسبة', 'Save rate')}</button></form>
    ${dataTable({ id: 'adfin', title: tr('أرصدة الشركات', 'Company balances'), rows, defaultSort: 'payable', export: true, exportName: 'company-balances', search: false,
      csvCols: [{ label: tr('الشركة', 'Company'), csv: (r) => r._n }, { label: tr('النسبة', 'Rate'), csv: (r) => effectiveRate(r) }, { label: 'Gross', csv: (r) => r.f.gross }, { label: tr('العمولة', 'Commission'), csv: (r) => r.f.commission }, { label: tr('الصافي', 'Net'), csv: (r) => r.f.net }, { label: tr('محجوز', 'Held'), csv: (r) => r.f.escrow }, { label: tr('مستحق', 'Payable'), csv: (r) => r.f.payable }, { label: tr('تم تحويله', 'Settled'), csv: (r) => r.f.settled }],
      cols: [{ key: '_n', label: tr('الشركة', 'Company'), render: (r) => `<div class="row">${coLogo(r)}<span>${esc(r._n)}</span></div>` }, { key: 'rate', label: tr('النسبة', 'Rate'), sortVal: (r) => effectiveRate(r), render: (r) => `<button class="btn-link" data-a="co-view" data-id="${r.id}">${effectiveRate(r)}٪</button>` }, { key: 'gross', label: tr('الإجمالي', 'Gross'), sortVal: (r) => r.f.gross, render: (r) => `<span class="num">${money(r.f.gross)}</span>` }, { key: 'comm', label: tr('العمولة', 'Commission'), sortVal: (r) => r.f.commission, render: (r) => `<span class="num">${money(r.f.commission)}</span>` }, { key: 'escrow', label: tr('محجوز', 'Held'), sortVal: (r) => r.f.escrow, render: (r) => `<span class="num">${money(r.f.escrow)}</span>` }, { key: 'payable', label: tr('مستحق', 'Payable'), sortVal: (r) => r.f.payable, render: (r) => `<b class="num" style="color:var(--navy)">${money(r.f.payable)}</b>` }, { key: 'settled', label: tr('تم تحويله', 'Settled'), sortVal: (r) => r.f.settled, render: (r) => `<span class="num">${money(r.f.settled)}</span>` }, { key: '', label: '', sort: false, render: (r) => `<button class="btn btn-soft btn-sm" data-a="st-open" data-id="${r.id}" ${r.f.payable ? '' : 'disabled'}>${tr('تسجيل تسوية', 'Record payout')}</button>` }] })}
  </div>
  <div style="margin-top:20px">${dataTable({ id: 'adtx', title: tr('المعاملات المالية', 'Financial transactions'), rows: txs, defaultSort: 'createdAt', export: true, exportName: 'transactions', searchText: (r) => r.b.ref + ' ' + r.txn,
    filters: [{ key: 'st', label: tr('كل الأنواع', 'All types'), options: [['paid', tr('مدفوع', 'Paid')], ['failed', tr('فشل', 'Failed')], ['refund', tr('استرداد', 'Refund')]], test: (r, v) => r.status === v }, { key: 'm', label: tr('كل الطرق', 'All methods'), options: Object.entries(GATEWAYS).map(([k, g]) => [k, L(g.name)]), test: (r, v) => r.method === v }],
    csvCols: [{ label: tr('التاريخ', 'Date'), csv: (r) => r.createdAt }, { label: 'Ref', csv: (r) => r.b.ref }, { label: 'TXN', csv: (r) => r.txn }, { label: tr('الطريقة', 'Method'), csv: (r) => r.method }, { label: tr('المبلغ', 'Amount'), csv: (r) => r.amount }, { label: tr('العمولة', 'Commission'), csv: (r) => r.status === 'paid' ? r.b.commission : 0 }, { label: tr('الحالة', 'Status'), csv: (r) => r.status }],
    cols: [{ key: 'createdAt', label: tr('التاريخ', 'Date'), render: (r) => `<span class="small">${fmtDT(r.createdAt)}</span>` }, { key: 'ref', label: tr('الحجز', 'Booking'), sortVal: (r) => r.b.ref, render: (r) => `<button class="btn-link ref" data-a="ad-bk" data-id="${r.b.id}">${r.b.ref}</button>` }, { key: 'txn', label: tr('رقم العملية', 'Transaction'), render: (r) => `<span class="ref faint">${r.txn || '—'}</span>` }, { key: 'method', label: tr('الطريقة', 'Method'), render: (r) => esc(L(GATEWAYS[r.method].name)) }, { key: 'amount', label: tr('المبلغ', 'Amount'), render: (r) => `<b class="num" style="color:${r.amount < 0 ? 'var(--teal-700)' : 'var(--navy)'}">${money(r.amount)}</b>` }, { key: 'comm', label: tr('عمولة الحجز', 'Commission'), sort: false, render: (r) => r.status === 'paid' ? `<span class="num">${money(r.b.commission)}</span> <span class="xs faint">${r.b.commissionRate}٪</span>` : '—' }, { key: 'status', label: tr('الحالة', 'Status'), render: (r) => badge(PSTAT, r.status) }] })}</div>
  <style>@media(max-width:1100px){#fin-grid{grid-template-columns:1fr!important}}</style>`);
}
FORMS['ad-comm'] = (f) => { const d = validate(f, { commission: ['req', 'pct'] }); if (!d) return; tx((x) => { x.settings.commission = +d.commission; logAct(x, `تغيير العمولة الافتراضية إلى ${d.commission}٪`, `Default commission set to ${d.commission}%`); }); toast(tr('تم حفظ العمولة الافتراضية.', 'Default commission saved.')); render(); };
ACTIONS['st-open'] = (el) => { const c = compById(el.dataset.id), f = companyFinance(c.id); modal({ title: tr('تسجيل تسوية لـ ', 'Record payout to ') + esc(L(c.name)), body: `<form data-f="st" id="st-form" data-id="${c.id}" class="stack" novalidate><div class="callout">${ic('info')}<div>${tr('المستحق حاليًا', 'Currently payable')}: <b class="num">${money(f.payable)}</b></div></div>${inp('amount', tr('المبلغ المحوّل (ج.م)', 'Amount paid (EGP)'), f.payable, { type: 'number', attrs: `min="1" max="${f.payable}"` })}${sel('method', tr('الطريقة', 'Method'), [['تحويل بنكي', tr('تحويل بنكي', 'Bank transfer')], ['إنستاباي', 'InstaPay'], ['شيك', tr('شيك', 'Cheque')]], 'تحويل بنكي')}${inp('note', tr('البيان', 'Note'), tr('تسوية ', 'Settlement ') + fmtD(new Date(), { month: 'long', year: 'numeric' }))}</form>`, foot: `<button class="btn btn-ghost" data-a="close-modal">${tr('إلغاء', 'Cancel')}</button><button class="btn btn-primary" data-a="st-save">${tr('تسجيل', 'Record')}</button>` }); };
ACTIONS['st-save'] = () => $('#st-form').requestSubmit();
FORMS.st = (f) => { const max = companyFinance(f.dataset.id).payable; const d = validate(f, { amount: ['req', 'pos', (v) => +v <= max || tr(`أكبر من المستحق (${money(max)}).`, `More than payable (${money(max)}).`)] }); if (!d) return; tx((x) => { x.settlements.push({ id: uid('st'), companyId: f.dataset.id, amount: +d.amount, method: d.method, note: d.note, createdAt: new Date().toISOString() }); notify(x, 'company:' + f.dataset.id, { ar: 'تم تحويل مستحقاتك', en: 'Payout sent' }, { ar: `تم تحويل ${fmtN(+d.amount)} ج.م (${d.method}).`, en: `EGP ${fmtN(+d.amount)} sent (${d.method}).` }, '#/co/finance'); logAct(x, `تسوية ${fmtN(+d.amount)} ج.م لـ ${byId(x.companies, f.dataset.id).name.ar}`, `Payout EGP ${fmtN(+d.amount)} to ${byId(x.companies, f.dataset.id).name.en}`); }); closeModal(); toast(tr('تم تسجيل التسوية وإبلاغ الشركة.', 'Payout recorded and company notified.')); render(); };

/* content management */
function viewAdContent() {
  const s = db.settings, tab = UI.adCt || 'banners';
  const tabs = [['banners', tr('البانرات', 'Banners')], ['featured', tr('المميز في الرئيسية', 'Homepage featured')], ['offers', tr('العروض وأكواد الخصم', 'Offers & codes')], ['faq', tr('الأسئلة الشائعة', 'FAQ')], ['pages', tr('الصفحات الثابتة', 'Static pages')], ['broadcast', tr('إشعار عام', 'Broadcast')]];
  let body = '';
  if (tab === 'banners') body = s.banners.map((b) => `<form class="card card-pad" data-f="bn" data-id="${b.id}" novalidate><div class="grid" style="grid-template-columns:280px 1fr;gap:20px" id="bn-g"><div><img src="${imgSrc(b.art)}" alt="" style="border-radius:14px;aspect-ratio:16/9;object-fit:cover;width:100%">${sel('art', tr('الصورة', 'Image'), [['art:nile:1', tr('النيل', 'Nile')], ['art:sea:0', tr('البحر الأحمر', 'Red Sea')], ['art:oasis:1', tr('سيوة', 'Siwa')], ['art:temple:1', tr('الأقصر', 'Luxor')], ['art:coast:0', tr('الساحل', 'Coast')]], b.art)}</div><div class="form-grid">${inp('title', tr('العنوان', 'Title'), L(b.title), { full: true })}${inp('text', tr('النص', 'Text'), L(b.text), { full: true })}${inp('code', tr('كود الخصم', 'Promo code'), b.code, { attrs: 'dir="ltr"' })}${inp('link', tr('الرابط', 'Link'), b.link, { attrs: 'dir="ltr"' })}<label class="check"><input type="checkbox" name="active" value="1" ${b.active ? 'checked' : ''}>${tr('ظاهر في الرئيسية', 'Show on homepage')}</label><div style="text-align:end"><button class="btn btn-primary" type="submit">${tr('حفظ البانر', 'Save banner')}</button></div></div></div></form>`).join('') + '<style>@media(max-width:800px){#bn-g{grid-template-columns:1fr!important}}</style>';
  if (tab === 'featured') body = `<form class="card card-pad" data-f="feat" novalidate><h3>${tr('الرحلات المميزة', 'Featured trips')}</h3><p class="small muted" style="margin-bottom:12px">${tr('اختار الرحلات اللي تظهر في أعلى الرئيسية.', 'Pick trips to feature on the homepage.')}</p><div class="grid g2">${publicTrips().map((t) => `<label class="opt"><input type="checkbox" name="trips" value="${t.id}" ${s.featuredTrips.includes(t.id) ? 'checked' : ''}>${esc(L(t.title))}</label>`).join('')}</div><h3 style="margin-top:20px">${tr('الوجهات المميزة', 'Featured destinations')}</h3><div class="grid g3" style="margin-top:10px">${db.destinations.map((d) => `<label class="opt"><input type="checkbox" name="dests" value="${d.id}" ${d.featured ? 'checked' : ''}>${esc(L(d.name))}</label>`).join('')}</div><div style="text-align:end;margin-top:14px"><button class="btn btn-primary" type="submit">${tr('حفظ', 'Save')}</button></div></form>`;
  if (tab === 'offers') body = `<div class="card"><div class="card-h"><h3>${tr('أكواد الخصم', 'Promo codes')}</h3><button class="btn btn-primary btn-sm" data-a="of-open">${ic('plus')}${tr('عرض جديد', 'New offer')}</button></div><div class="tbl-wrap"><table class="tbl"><thead><tr><th>${tr('الكود', 'Code')}</th><th>${tr('الخصم', 'Discount')}</th><th>${tr('الوجهات', 'Destinations')}</th><th>${tr('ينتهي', 'Ends')}</th><th>${tr('الحالة', 'Status')}</th><th></th></tr></thead><tbody>${s.offers.map((o) => `<tr><td><span class="code" style="color:var(--navy);border-color:var(--sand-700)">${esc(o.code)}</span></td><td class="num">${o.percent}٪</td><td class="small">${o.dests.length ? o.dests.map((d) => L(destById(d).name)).join('، ') : tr('كل الوجهات', 'All')}</td><td>${fmtD(o.until)}</td><td><span class="badge ${o.active ? 'b-ok' : 'b-mute'}">${o.active ? tr('فعال', 'Active') : tr('متوقف', 'Off')}</span></td><td><div class="row" style="gap:6px;justify-content:flex-end"><button class="icon-btn" data-a="of-open" data-id="${o.id}" aria-label="${tr('تعديل', 'Edit')}">${ic('edit')}</button><button class="icon-btn" style="color:var(--bad)" data-a="of-del" data-id="${o.id}" aria-label="${tr('حذف', 'Delete')}">${ic('trash')}</button></div></td></tr>`).join('')}</tbody></table></div></div>`;
  if (tab === 'faq') body = `<div class="card"><div class="card-h"><h3>${tr('الأسئلة الشائعة', 'FAQ')}</h3><button class="btn btn-primary btn-sm" data-a="faq-open">${ic('plus')}${tr('سؤال جديد', 'New question')}</button></div><div class="card-pad">${s.faq.map((x, i) => `<div class="rev row between" style="align-items:flex-start"><div><b style="color:var(--navy)">${esc(L(x.q))}</b><p class="small muted">${esc(L(x.a))}</p></div><div class="row" style="gap:6px"><button class="icon-btn" data-a="faq-open" data-i="${i}" aria-label="${tr('تعديل', 'Edit')}">${ic('edit')}</button><button class="icon-btn" style="color:var(--bad)" data-a="faq-del" data-i="${i}" aria-label="${tr('حذف', 'Delete')}">${ic('trash')}</button></div></div>`).join('')}</div></div>`;
  if (tab === 'pages') body = Object.entries(s.pages).map(([k, p]) => `<form class="card card-pad stack" data-f="pg" data-k="${k}" style="margin-bottom:14px" novalidate><div class="row between"><h3>${esc(L(p.title))}</h3><a class="btn-link small" href="#/page/${k}">${tr('عرض', 'View')}</a></div>${inp('title', tr('العنوان', 'Title'), L(p.title))}${txa('body', tr('المحتوى', 'Content'), L(p.body), { rows: 4 })}<div style="text-align:end"><button class="btn btn-ghost" type="submit">${tr('حفظ الصفحة', 'Save page')}</button></div></form>`).join('');
  if (tab === 'broadcast') body = `<form class="card card-pad stack" data-f="bc" novalidate style="max-width:640px"><h3>${tr('إرسال إشعار داخل التطبيق', 'Send an in‑app notification')}</h3>${sel('to', tr('إلى', 'To'), [['customers', tr('كل العملاء', 'All customers')], ['companies', tr('كل الشركات المعتمدة', 'All approved companies')]], 'customers')}${inp('title', tr('العنوان', 'Title'), '')}${txa('body', tr('الرسالة', 'Message'), '', { rows: 3 })}${inp('link', tr('رابط (اختياري)', 'Link (optional)'), '#/trips', { attrs: 'dir="ltr"' })}<div><button class="btn btn-primary" type="submit">${ic('bell')}${tr('إرسال', 'Send')}</button></div></form>`;
  return dashLayout('admin', tr('إدارة المحتوى', 'Content'), `<div class="tabs">${tabs.map(([k, l]) => `<button class="${k === tab ? 'on' : ''}" data-a="adct-tab" data-k="${k}">${l}</button>`).join('')}</div>${body}`);
}
ACTIONS['adct-tab'] = (el) => { UI.adCt = el.dataset.k; render(); };
const setL = (o, v) => (LANG === 'en' ? { ar: (o && o.ar) || v, en: v } : { ar: v, en: (o && o.en) || '' });
FORMS.bn = (f) => { const d = validate(f, { title: ['req'], text: ['req'] }); if (!d) return; tx((x) => { const b = x.settings.banners.find((y) => y.id === f.dataset.id); Object.assign(b, { title: setL(b.title, d.title), text: setL(b.text, d.text), code: d.code, link: d.link || '#/trips', art: d.art, active: !!d.active }); }); toast(tr('تم حفظ البانر.', 'Banner saved.')); render(); };
FORMS.feat = (f) => { const d = formData(f); const ts = [].concat(d.trips || []), ds = [].concat(d.dests || []); tx((x) => { x.settings.featuredTrips = ts; x.destinations.forEach((y) => { y.featured = ds.includes(y.id); }); }); toast(tr('تم حفظ المحتوى المميز.', 'Featured content saved.')); render(); };
ACTIONS['of-open'] = (el) => { const o = el.dataset.id ? db.settings.offers.find((x) => x.id === el.dataset.id) : { code: '', percent: 10, dests: [], until: iso(addDays(TODAY, 30)), active: true }; modal({ title: el.dataset.id ? tr('تعديل العرض', 'Edit offer') : tr('عرض جديد', 'New offer'), body: `<form data-f="of" id="of-form" data-id="${el.dataset.id || ''}" class="form-grid" novalidate>${inp('code', tr('الكود', 'Code'), o.code, { attrs: 'dir="ltr" style="text-transform:uppercase"' })}${inp('percent', tr('نسبة الخصم ٪', 'Discount %'), o.percent, { type: 'number', attrs: 'min="1" max="50"' })}${inp('until', tr('ينتهي في', 'Ends on'), o.until, { type: 'date' })}<label class="check" style="align-self:end;padding-bottom:10px"><input type="checkbox" name="active" value="1" ${o.active ? 'checked' : ''}>${tr('فعال', 'Active')}</label><div class="field full"><span class="lbl">${tr('الوجهات (اتركها فارغة = كل الوجهات)', 'Destinations (none = all)')}</span><div class="grid g3" style="gap:4px">${db.destinations.map((d) => `<label class="opt"><input type="checkbox" name="dests" value="${d.id}" ${o.dests.includes(d.id) ? 'checked' : ''}>${esc(L(d.name))}</label>`).join('')}</div></div></form>`, foot: `<button class="btn btn-ghost" data-a="close-modal">${tr('إلغاء', 'Cancel')}</button><button class="btn btn-primary" data-a="of-save">${tr('حفظ', 'Save')}</button>` }); };
ACTIONS['of-save'] = () => $('#of-form').requestSubmit();
FORMS.of = (f) => { const d = validate(f, { code: ['req', (v) => /^[A-Za-z0-9]{3,16}$/.test(v) || tr('حروف وأرقام إنجليزي فقط (٣–١٦).', 'Letters and numbers only (3–16).'), (v) => !db.settings.offers.some((o) => o.code.toUpperCase() === v.toUpperCase() && o.id !== f.dataset.id) || tr('الكود مستخدم.', 'Code already exists.')], percent: ['req', 'pct', 'pos'], until: ['req', 'future'] }); if (!d) return; const data = { code: d.code.toUpperCase(), percent: +d.percent, until: d.until, active: !!d.active, dests: [].concat(d.dests || []) }; tx((x) => { const o = x.settings.offers.find((y) => y.id === f.dataset.id); o ? Object.assign(o, data) : x.settings.offers.push({ id: uid('of'), ...data }); }); closeModal(); toast(tr('تم حفظ العرض.', 'Offer saved.')); render(); };
ACTIONS['of-del'] = async (el) => { if (!(await confirmDialog({ title: tr('حذف العرض؟', 'Delete offer?'), text: tr('الكود هيبطل يشتغل فورًا.', 'The code stops working immediately.'), ok: tr('حذف', 'Delete'), danger: true }))) return; tx((x) => { x.settings.offers = x.settings.offers.filter((o) => o.id !== el.dataset.id); }); toast(tr('تم حذف العرض.', 'Offer deleted.')); render(); };
ACTIONS['faq-open'] = (el) => { const i = el.dataset.i, x = i != null ? db.settings.faq[+i] : null; modal({ title: x ? tr('تعديل سؤال', 'Edit question') : tr('سؤال جديد', 'New question'), body: `<form data-f="faq" id="faq-form" data-i="${i == null ? '' : i}" class="stack" novalidate>${inp('q', tr('السؤال', 'Question'), x ? L(x.q) : '')}${txa('a', tr('الإجابة', 'Answer'), x ? L(x.a) : '', { rows: 4 })}</form>`, foot: `<button class="btn btn-ghost" data-a="close-modal">${tr('إلغاء', 'Cancel')}</button><button class="btn btn-primary" data-a="faq-save">${tr('حفظ', 'Save')}</button>` }); };
ACTIONS['faq-save'] = () => $('#faq-form').requestSubmit();
FORMS.faq = (f) => { const d = validate(f, { q: ['req'], a: ['req'] }); if (!d) return; tx((x) => { const i = f.dataset.i; if (i !== '') { const o = x.settings.faq[+i]; o.q = setL(o.q, d.q); o.a = setL(o.a, d.a); } else x.settings.faq.push({ q: setL(null, d.q), a: setL(null, d.a) }); }); closeModal(); toast(tr('تم الحفظ.', 'Saved.')); render(); };
ACTIONS['faq-del'] = async (el) => { if (!(await confirmDialog({ title: tr('حذف السؤال؟', 'Delete question?'), text: tr('هيتشال من صفحة الأسئلة الشائعة.', 'It will be removed from the FAQ page.'), ok: tr('حذف', 'Delete'), danger: true }))) return; tx((x) => x.settings.faq.splice(+el.dataset.i, 1)); toast(tr('تم الحذف.', 'Deleted.')); render(); };
FORMS.pg = (f) => { const d = validate(f, { title: ['req'], body: ['req'] }); if (!d) return; tx((x) => { const p = x.settings.pages[f.dataset.k]; p.title = setL(p.title, d.title); p.body = setL(p.body, d.body); }); toast(tr('تم حفظ الصفحة.', 'Page saved.')); };
FORMS.bc = (f) => { const d = validate(f, { title: ['req'], body: ['req'] }); if (!d) return; const n = tx((x) => { const targets = d.to === 'customers' ? x.users.filter((u) => u.role === 'customer' && u.status === 'active') : x.users.filter((u) => u.role === 'company' && (byId(x.companies, u.companyId) || {}).status === 'approved'); targets.forEach((u) => notify(x, u.id, { ar: d.title, en: d.title }, { ar: d.body, en: d.body }, d.link)); return targets.length; }); f.reset(); toast(tr(`تم إرسال الإشعار إلى ${n} حساب.`, `Sent to ${n} accounts.`)); };

/* taxonomy */
function viewAdTaxonomy() {
  const used = (k, id) => db.trips.filter((t) => t[k] === id).length;
  return dashLayout('admin', tr('الوجهات والتصنيفات', 'Destinations & categories'), `<div class="grid g2" style="align-items:start">
    <div class="card"><div class="card-h"><h3>${tr('الوجهات', 'Destinations')}</h3><button class="btn btn-primary btn-sm" data-a="tx-open" data-k="dest">${ic('plus')}${tr('إضافة', 'Add')}</button></div><div class="tbl-wrap"><table class="tbl"><tbody>${db.destinations.map((d) => `<tr><td><div class="row"><img src="${artURL(d.art, 0)}" alt="" style="width:48px;height:34px;object-fit:cover;border-radius:7px"><div><b style="color:var(--navy)">${esc(L(d.name))}</b><div class="xs muted">${esc(L(d.region))}</div></div></div></td><td class="small muted">${tr(`${used('destId', d.id)} رحلة`, `${used('destId', d.id)} trips`)}</td><td><div class="row" style="gap:6px;justify-content:flex-end"><button class="icon-btn" data-a="tx-open" data-k="dest" data-id="${d.id}" aria-label="${tr('تعديل', 'Edit')}">${ic('edit')}</button><button class="icon-btn" style="color:var(--bad)" data-a="tx-del" data-k="dest" data-id="${d.id}" aria-label="${tr('حذف', 'Delete')}">${ic('trash')}</button></div></td></tr>`).join('')}</tbody></table></div></div>
    <div class="card"><div class="card-h"><h3>${tr('تصنيفات الرحلات', 'Trip categories')}</h3><button class="btn btn-primary btn-sm" data-a="tx-open" data-k="cat">${ic('plus')}${tr('إضافة', 'Add')}</button></div><div class="tbl-wrap"><table class="tbl"><tbody>${db.categories.map((c) => `<tr><td><b style="color:var(--navy)">${esc(L(c.name))}</b></td><td class="small muted">${tr(`${used('catId', c.id)} رحلة`, `${used('catId', c.id)} trips`)}</td><td><div class="row" style="gap:6px;justify-content:flex-end"><button class="icon-btn" data-a="tx-open" data-k="cat" data-id="${c.id}" aria-label="${tr('تعديل', 'Edit')}">${ic('edit')}</button><button class="icon-btn" style="color:var(--bad)" data-a="tx-del" data-k="cat" data-id="${c.id}" aria-label="${tr('حذف', 'Delete')}">${ic('trash')}</button></div></td></tr>`).join('')}</tbody></table></div></div></div>`);
}
ACTIONS['tx-open'] = (el) => { const isD = el.dataset.k === 'dest', o = el.dataset.id ? (isD ? destById(el.dataset.id) : catById(el.dataset.id)) : null; modal({ title: o ? tr('تعديل', 'Edit') : tr('إضافة', 'Add'), body: `<form data-f="txf" id="tx-form" data-k="${el.dataset.k}" data-id="${el.dataset.id || ''}" class="form-grid" novalidate>${inp('ar', tr('الاسم بالعربي', 'Arabic name'), o ? o.name.ar : '')}${inp('en', tr('الاسم بالإنجليزي', 'English name'), o ? o.name.en : '', { attrs: 'dir="ltr"' })}${isD ? inp('region', tr('المنطقة', 'Region'), o ? L(o.region) : '') + sel('art', tr('الرسم', 'Artwork'), [['sea', tr('بحر', 'Sea')], ['sinai', tr('جبال وبحر', 'Mountains & sea')], ['temple', tr('معابد', 'Temples')], ['nile', tr('نيل', 'Nile')], ['oasis', tr('واحة', 'Oasis')], ['coast', tr('ساحل', 'Coast')], ['desert', tr('صحراء', 'Desert')], ['pyramids', tr('أهرامات', 'Pyramids')]], o ? o.art : 'sea') : ''}</form>`, foot: `<button class="btn btn-ghost" data-a="close-modal">${tr('إلغاء', 'Cancel')}</button><button class="btn btn-primary" data-a="tx-save">${tr('حفظ', 'Save')}</button>` }); };
ACTIONS['tx-save'] = () => $('#tx-form').requestSubmit();
FORMS.txf = (f) => { const d = validate(f, { ar: ['req'], en: ['req'] }); if (!d) return; const isD = f.dataset.k === 'dest'; tx((x) => { const list = isD ? x.destinations : x.categories; const o = byId(list, f.dataset.id); const data = { name: { ar: d.ar, en: d.en }, ...(isD ? { region: { ar: d.region, en: d.region }, art: d.art } : {}) }; o ? Object.assign(o, data) : list.push({ id: d.en.toLowerCase().replace(/[^a-z0-9]+/g, '') || uid('x'), featured: false, ...data }); }); closeModal(); toast(tr('تم الحفظ.', 'Saved.')); render(); };
ACTIONS['tx-del'] = async (el) => { const isD = el.dataset.k === 'dest', n = db.trips.filter((t) => t[isD ? 'destId' : 'catId'] === el.dataset.id).length; if (n) return toast(tr(`مينفعش تتحذف لأن عليها ${n} رحلة. انقل الرحلات الأول.`, `Can’t delete: ${n} trips use it. Move them first.`), 'bad'); if (!(await confirmDialog({ title: tr('حذف؟', 'Delete?'), text: tr('العنصر ده مش مستخدم في أي رحلة وهيتحذف.', 'Not used by any trip; it will be deleted.'), ok: tr('حذف', 'Delete'), danger: true }))) return; tx((x) => { if (isD) x.destinations = x.destinations.filter((y) => y.id !== el.dataset.id); else x.categories = x.categories.filter((y) => y.id !== el.dataset.id); }); toast(tr('تم الحذف.', 'Deleted.')); render(); };

function viewAdSettings() {
  return dashLayout('admin', tr('الإعدادات', 'Settings'), `<div class="grid g2" style="align-items:start"><form class="card card-pad stack" data-f="ad-set" novalidate><h3>${tr('إعدادات الحجز', 'Booking settings')}</h3>${inp('hold', tr('مدة حجز المقاعد أثناء الدفع (دقيقة)', 'Seat hold during payment (minutes)'), db.settings.holdMinutes, { type: 'number', attrs: 'min="5" max="60"' })}${inp('commission', tr('العمولة الافتراضية ٪', 'Default commission %'), db.settings.commission, { type: 'number', attrs: 'min="0" max="50" step="0.5"' })}<div><button class="btn btn-primary" type="submit">${tr('حفظ', 'Save')}</button></div></form>
  <div class="card card-pad stack"><h3>${tr('البيانات التجريبية', 'Demo data')}</h3><p class="small muted">${tr('كل البيانات محفوظة في متصفحك فقط (localStorage). إعادة الضبط بترجع الشركات والرحلات والحجوزات الأصلية.', 'All data lives in this browser only (localStorage). Resetting restores the original companies, trips and bookings.')}</p>${MEMORY_ONLY ? `<div class="callout warn">${ic('alert')}<div>${tr('المتصفح مانع التخزين، فالتعديلات هتضيع لما تقفل الصفحة.', 'Browser storage is blocked, so changes are lost when you close the page.')}</div></div>` : ''}<div><button class="btn btn-danger-soft" data-a="reset-demo">${ic('undo')}${tr('إعادة ضبط البيانات التجريبية', 'Reset demo data')}</button></div></div></div>`);
}
FORMS['ad-set'] = (f) => { const d = validate(f, { hold: ['req', 'int', (v) => (+v >= 5 && +v <= 60) || tr('من ٥ إلى ٦٠ دقيقة.', '5 to 60 minutes.')], commission: ['req', 'pct'] }); if (!d) return; tx((x) => { x.settings.holdMinutes = +d.hold; x.settings.commission = +d.commission; }); toast(tr('تم حفظ الإعدادات.', 'Settings saved.')); render(); };
